node --input-type=module -e "
import assert from 'node:assert/strict';
import { createPushGate } from './bot.mjs';
const u = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const d = (s) => new Date(s);
let g = createPushGate();
assert.deepEqual(g.attempt(u, d('2026-10-23T13:30:00Z')), { allowed: false, reason: 'quiet_hours' });   // 22:30 JST
assert.deepEqual(g.attempt(u, d('2026-10-23T13:00:00Z')), { allowed: false, reason: 'quiet_hours' });   // 22:00 JST start included
assert.deepEqual(g.attempt(u, d('2026-10-23T21:59:00Z')), { allowed: false, reason: 'quiet_hours' });   // 06:59 JST
assert.deepEqual(g.attempt(u, d('2026-10-23T22:00:00Z')), { allowed: true, reason: null });            // 07:00 JST end excluded
assert.deepEqual(g.attempt(u, d('2026-10-24T03:00:00Z')), { allowed: true, reason: null });            // 12:00 JST Oct 24
assert.deepEqual(g.attempt(u, d('2026-10-24T04:00:00Z')), { allowed: true, reason: null });            // 13:00 JST Oct 24
assert.deepEqual(g.attempt(u, d('2026-10-24T05:00:00Z')), { allowed: false, reason: 'daily_cap_reached' }); // 3rd already sent that JST day
assert.deepEqual(g.attempt(u, d('2026-10-24T06:00:00Z')), { allowed: false, reason: 'daily_cap_reached' });
// next local day resets the count
assert.deepEqual(g.attempt(u, d('2026-10-24T16:00:00Z')), { allowed: true, reason: null }); // Oct 25 01:00 JST
// independent gates and per-call settings
const g2 = createPushGate();
assert.equal(g2.attempt({ ...u, dailyCap: 0 }, d('2026-10-24T03:00:00Z')).reason, 'daily_cap_reached');
assert.equal(g2.attempt({ ...u, timeZone: 'Mars/Base' }, d('2026-10-24T03:00:00Z')).reason, 'unknown_time_zone');
assert.equal(g2.attempt({ ...u, quietStart: '7:00' }, d('2026-10-24T03:00:00Z')).reason, 'invalid_quiet_hours');
assert.equal(g2.attempt(u, new Date('x')).reason, 'invalid_now');
// same-day window that does not wrap, New York DST day
const ny = { id: 'u_1', timeZone: 'America/New_York', quietStart: '13:00', quietEnd: '14:00', dailyCap: 5 };
assert.equal(createPushGate().attempt(ny, d('2026-03-08T17:30:00Z')).reason, 'quiet_hours'); // 13:30 EDT
assert.equal(createPushGate().attempt(ny, d('2026-03-08T18:00:00Z')).allowed, true);       // 14:00 EDT end excluded
console.log('all checks passed');
"

